package crmoutbox

import (
	_ "embed"
	"encoding/json"
	"sort"
)

// queuesJSON is the CRM's eventToQueueMap (infrastructure/events/eventPublisher.js),
// generated by deploy/sombra-outbox/mapa-filas.mjs. CI compares it with the
// CRM main branch so the shadow's "proposed destination" does not go stale.
//
//go:embed queues.json
var queuesJSON []byte

var queueMap = func() map[string][]string {
	m := map[string][]string{}
	if err := json.Unmarshal(queuesJSON, &m); err != nil {
		panic("crmoutbox: queues.json: " + err.Error())
	}
	return m
}()

// externalSendQueues are the CRM queues whose workers can send something to a
// person outside the clinic (WhatsApp or e-mail), read from the workers at
// fono-inova-crm-back 529ca0f:
//   - notification            workers/notificationOrchestratorWorker.js (sendTextMessage, sendTemplateMessage, e-mail)
//   - whatsapp-notification   domains/whatsapp/workers/whatsappSendWorker.js
//   - followup-processing     workers/followupOrchestratorWorker.js (sendTextMessage)
//   - whatsapp-auto-reply     domains/whatsapp/workers/whatsappAutoReplyWorker.js (Amanda)
//   - lead-orchestrator-v2    domains/whatsapp/workers/leadOrchestratorWorker.v2.js ("enviar WhatsApp inteligente")
//
// Every other queue updates read models or runs internal processing. The
// shadow uses this only to label its report; it never publishes anything.
var externalSendQueues = map[string]bool{
	"notification": true, "whatsapp-notification": true, "followup-processing": true,
	"whatsapp-auto-reply": true, "lead-orchestrator-v2": true,
}

// Destinations returns the queues the CRM dispatcher publishes an entry of
// this type to. known is false when the type is not in the map: the
// dispatcher fails such an entry with UNKNOWN_EVENT_TYPE. An empty, known
// list means "marked published without any queue".
func Destinations(eventType string) (queues []string, known bool) {
	q, ok := queueMap[eventType]
	if !ok {
		return nil, false
	}
	return append([]string(nil), q...), true
}

// ExternalSend reports whether a queue's worker can send to a person outside
// the clinic (WhatsApp or e-mail).
func ExternalSend(queue string) bool { return externalSendQueues[queue] }

// KnownTypes lists every event type the dispatcher can route, sorted.
func KnownTypes() []string {
	out := make([]string, 0, len(queueMap))
	for k := range queueMap {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}
